const extractTextFromDocx = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = async (event) => {
      const arrayBuffer = event.target?.result as ArrayBuffer;
      try {
        const result = await mammoth.extractRawText({ arrayBuffer });
        resolve(result.value);
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
};

const extractTextFromExcel = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const arrayBuffer = event.target?.result as ArrayBuffer;
        const workbook = XLSX.read(arrayBuffer, { type: "array" });
        let textResult = "";
        workbook.SheetNames.forEach((sheetName) => {
          textResult += `Sheet: ${sheetName}\n`;
          const sheet = workbook.Sheets[sheetName];
          const csv = XLSX.utils.sheet_to_csv(sheet);
          textResult += csv + "\n\n";
        });
        resolve(textResult);
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = reject;
    reader.readAsArrayBuffer(file);
  });
};

/** Pull the text out of a PDF, page by page.
 *
 *  The AI path can only read text, so a PDF handed over as bytes is silently
 *  ignored. pdf.js is loaded on demand — it is large, and most sessions never
 *  upload a PDF. A PDF that is really a scan has no text layer and comes back
 *  nearly empty; the caller checks for that and says so rather than generating
 *  a plan from nothing. */
const extractTextFromPdf = async (file: File): Promise<string> => {
  const pdfjs: any = await import("pdfjs-dist");
  // Vite rewrites this URL at build time and emits the worker as an asset.
  pdfjs.GlobalWorkerOptions.workerSrc = new URL(
    "pdfjs-dist/build/pdf.worker.min.mjs",
    import.meta.url,
  ).toString();

  const data = await file.arrayBuffer();
  const pdf = await pdfjs.getDocument({ data }).promise;
  const pages: string[] = [];
  for (let n = 1; n <= pdf.numPages; n++) {
    const page = await pdf.getPage(n);
    const content = await page.getTextContent();
    // Rebuild the lines. pdf.js hands back positioned runs, not lines, so
    // joining them all with spaces turns a list of weeks into one run-on
    // sentence — and a lesson plan flattened that way reads as prose about a
    // single topic, which is exactly how it then gets rewritten. `hasEOL`
    // marks a line end; the y-coordinate is the fallback for older files.
    let text = "";
    let lastY: number | null = null;
    for (const it of content.items as any[]) {
      if (typeof it.str !== "string") continue;
      const y = Array.isArray(it.transform) ? it.transform[5] : null;
      const newLine = lastY !== null && y !== null && Math.abs(y - lastY) > 2;
      if (newLine && !text.endsWith("\n")) text += "\n";
      text += it.str;
      if (it.hasEOL) text += "\n";
      lastY = y;
    }
    const tidy = text
      .split("\n")
      .map((l) => l.replace(/[ \t]+/g, " ").trim())
      .filter(Boolean)
      .join("\n");
    if (tidy) pages.push(`--- Page ${n} ---\n${tidy}`);
  }
  await pdf.destroy?.();
  return pages.join("\n\n");
};

// Extract readable text from a PowerPoint (.pptx) — a zip of slide XML files.
const extractTextFromPptx = async (file: File): Promise<string> => {
  const arrayBuffer = await file.arrayBuffer();
  const zip = await JSZip.loadAsync(arrayBuffer);
  const decodeEntities = (s: string) =>
    s
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'");

  const slideNames = Object.keys(zip.files)
    .filter((n) => /^ppt\/slides\/slide\d+\.xml$/.test(n))
    .sort((a, b) => {
      const na = parseInt(a.match(/slide(\d+)\.xml/)?.[1] || "0", 10);
      const nb = parseInt(b.match(/slide(\d+)\.xml/)?.[1] || "0", 10);
      return na - nb;
    });

  let out = "";
  for (let i = 0; i < slideNames.length; i++) {
    const xml = await zip.files[slideNames[i]].async("string");
    const runs = xml.match(/<a:t[^>]*>([\s\S]*?)<\/a:t>/g) || [];
    const slideText = runs
      .map((t) => decodeEntities(t.replace(/<a:t[^>]*>|<\/a:t>/g, "")))
      .join(" ")
      .replace(/\s+/g, " ")
      .trim();
    if (slideText) out += `Slide ${i + 1}: ${slideText}\n\n`;
  }
  return out.trim();
};

const extractTextFromTextFile = async (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      resolve(event.target?.result as string);
    };
    reader.onerror = reject;
    reader.readAsText(file);
  });
};

const prepareFileForGemini = async (
  file: File,
): Promise<{ mimeType: string; data: string }> => {
  const mimeType = file.type || "";
  const fileName = file.name.toLowerCase();

  // 1a. A PDF is read here into text. It used to be passed through as base64
  // for Gemini's multimodal support, but generation runs on a text-only model
  // that drops it — so the upload appeared to work and changed nothing.
  const isPdf = mimeType === "application/pdf" || fileName.endsWith(".pdf");
  if (isPdf) {
    try {
      const extractedText = await extractTextFromPdf(file);
      if (extractedText.trim().length > 40) {
        return {
          mimeType: "text/plain",
          data: btoa(unescape(encodeURIComponent(extractedText))),
        };
      }
      // Falls through to the byte path below, which the caller treats as
      // unreadable — a scanned PDF has no text to find.
      console.warn("PDF has no text layer (likely a scan):", file.name);
    } catch (err) {
      console.error("Error reading PDF:", err);
    }
  }

  // 1b. Images still go through as bytes for the multimodal path.
  const isImage = mimeType.startsWith("image/");

  if (isImage || isPdf) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const result = reader.result as string;
        const base64Data = result.split(",")[1];
        resolve({
          mimeType: isPdf ? "application/pdf" : mimeType,
          data: base64Data,
        });
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  // 2. If it is a Word document (.docx)
  if (
    fileName.endsWith(".docx") ||
    mimeType ===
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
  ) {
    try {
      const extractedText = await extractTextFromDocx(file);
      const base64Text = btoa(unescape(encodeURIComponent(extractedText)));
      return {
        mimeType: "text/plain",
        data: base64Text,
      };
    } catch (err) {
      console.error("Error reading Word document:", err);
    }
  }

  // 3. If it is a Spreadsheet/Excel/CSV (.xlsx, .xls, .csv)
  if (
    fileName.endsWith(".xlsx") ||
    fileName.endsWith(".xls") ||
    fileName.endsWith(".csv") ||
    mimeType === "application/vnd.ms-excel" ||
    mimeType ===
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" ||
    mimeType === "text/csv"
  ) {
    try {
      const extractedText = await extractTextFromExcel(file);
      const base64Text = btoa(unescape(encodeURIComponent(extractedText)));
      return {
        mimeType: "text/plain",
        data: base64Text,
      };
    } catch (err) {
      console.error("Error reading spreadsheet document:", err);
    }
  }

  // 3b. PowerPoint presentation (.pptx)
  if (
    fileName.endsWith(".pptx") ||
    mimeType ===
      "application/vnd.openxmlformats-officedocument.presentationml.presentation"
  ) {
    try {
      const extractedText = await extractTextFromPptx(file);
      const base64Text = btoa(unescape(encodeURIComponent(extractedText)));
      return {
        mimeType: "text/plain",
        data: base64Text,
      };
    } catch (err) {
      console.error("Error reading PowerPoint document:", err);
    }
  }

  // 4. Default / Text Fallback (Plain Text, Markdown, html, JSON, code, etc.)
  try {
    const text = await extractTextFromTextFile(file);
    const base64Text = btoa(unescape(encodeURIComponent(text)));
    return {
      mimeType: "text/plain",
      data: base64Text,
    };
  } catch (err) {
    console.error("Fallback text reader error, trying binary base64:", err);
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const result = reader.result as string;
        resolve({
          mimeType: mimeType || "application/octet-stream",
          data: result.split(",")[1],
        });
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }
};

