// Admin sections that are switched off.
//  - LOCKED  : still listed, shown with a padlock, cannot be opened.
//  - HIDDEN  : removed from the menu entirely.
// The screens themselves are untouched — empty these lists to turn a section
// back on.
const ADMIN_LOCKED_TABS = [
  "timetable",
  "assignments",
  "duty",
  "classrooms",
  "cover",
];
const ADMIN_HIDDEN_TABS = ["sso"];
const isAdminTabBlocked = (tab: string): boolean =>
  ADMIN_LOCKED_TABS.includes(tab) || ADMIN_HIDDEN_TABS.includes(tab);

// Is this nav item the one the current tab sits under?
const isAdminNavActive = (itemId: string, tab: string): boolean =>
  itemId === tab ||
  (itemId === "timetable" &&
    ["assignments", "duty", "classrooms"].includes(tab)) ||
  (itemId === "teachers" && tab === "members");

const adminNavLabel = (tab: string): string => {
  for (const item of ADMIN_NAV) {
    const child = item.children?.find((c) => c.id === tab);
    if (child) return child.label;
    if (item.id === tab) return item.label;
  }
  return "";
};

const getWeekFromDate = (dateStr: string): number | null => {
  if (!dateStr) return null;
  const cleaned = dateStr.trim();
  if (!cleaned) return null;

  // Try clean standard ISO format parsing first
  let d = new Date(cleaned);

  // If Date is invalid or has unusual formats, let's try mapping common school date notation (e.g. "13/4", "13/4/2026", "13-4")
  if (isNaN(d.getTime())) {
    const parts = cleaned.split(/[-/.]/);
    if (parts.length >= 2) {
      const day = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1; // 0-indexed month
      const year = parts.length >= 3 ? parseInt(parts[2], 10) : 2026;
      const fullYear = year < 100 ? 2000 + year : year;
      if (!isNaN(day) && !isNaN(month) && !isNaN(fullYear)) {
        d = new Date(fullYear, month, day);
      }
    }
  }

  if (isNaN(d.getTime())) return null;

  const month = d.getMonth() + 1; // 1-12
  const day = d.getDate();
  const year = d.getFullYear() || 2026;

  const mmdd = month * 100 + day;

  // Hardcoded academic 2026 weekly boundaries corresponding to trackerWeeks labels
  if (mmdd >= 413 && mmdd <= 419) return 1; // 13/4-17/4
  if (mmdd >= 420 && mmdd <= 426) return 2; // 20/4-24/4
  if (mmdd >= 427 && mmdd <= 503) return 3; // 27/4-1/5
  if (mmdd >= 504 && mmdd <= 510) return 4; // 4/5-8/5
  if (mmdd >= 511 && mmdd <= 517) return 5; // 11/5-15/5
  if (mmdd >= 518 && mmdd <= 531) return 6; // 18/5-22/5 (including midterm break)
  if (mmdd >= 601 && mmdd <= 607) return 7; // 1/6-5/6
  if (mmdd >= 608 && mmdd <= 614) return 8; // 8/6-12/6
  if (mmdd >= 615 && mmdd <= 621) return 9; // 15/6-19/6
  if (mmdd >= 622 && mmdd <= 628) return 10; // 22/6-26/6
  if (mmdd >= 629 && mmdd <= 705) return 11; // 29/6-3/7
  if (mmdd >= 706 && mmdd <= 712) return 12; // 6/7-10/7
  if (mmdd >= 713 && mmdd <= 719) return 13; // 13/7-17/7
  if (mmdd >= 720 && mmdd <= 726) return 14; // 20/7-24/7
  if (mmdd >= 727 && mmdd <= 802) return 15; // 27/7-31/7

  // Dynamic fallback: find closest starting Monday for any other date in dynamic year
  const targetYear = year;
  const weekStarts = [
    { week: 1, date: new Date(targetYear, 3, 13) }, // April 13
    { week: 2, date: new Date(targetYear, 3, 20) }, // April 20
    { week: 3, date: new Date(targetYear, 3, 27) }, // April 27
    { week: 4, date: new Date(targetYear, 4, 4) }, // May 4
    { week: 5, date: new Date(targetYear, 4, 11) }, // May 11
    { week: 6, date: new Date(targetYear, 4, 18) }, // May 18
    { week: 7, date: new Date(targetYear, 5, 1) }, // June 1
    { week: 8, date: new Date(targetYear, 5, 8) }, // June 8
    { week: 9, date: new Date(targetYear, 5, 15) }, // June 15
    { week: 10, date: new Date(targetYear, 5, 22) }, // June 22
    { week: 11, date: new Date(targetYear, 5, 29) }, // June 29
    { week: 12, date: new Date(targetYear, 6, 6) }, // July 6
    { week: 13, date: new Date(targetYear, 6, 13) }, // July 13
    { week: 14, date: new Date(targetYear, 6, 20) }, // July 20
    { week: 15, date: new Date(targetYear, 6, 27) }, // July 27
  ];

  let closestWeek = 1;
  let minDiff = Infinity;
  for (const ws of weekStarts) {
    const diff = Math.abs(d.getTime() - ws.date.getTime());
    if (diff < minDiff) {
      minDiff = diff;
      closestWeek = ws.week;
    }
  }

  return closestWeek;
};

const getDateForWeek = (weekId: number): string => {
  const dates: Record<number, string> = {
    1: "2026-04-13",
    2: "2026-04-20",
    3: "2026-04-27",
    4: "2026-05-04",
    5: "2026-05-11",
    6: "2026-05-18",
    7: "2026-06-01",
    8: "2026-06-08",
    9: "2026-06-15",
    10: "2026-06-22",
    11: "2026-06-29",
    12: "2026-07-06",
    13: "2026-07-13",
    14: "2026-07-20",
    15: "2026-07-27",
  };
  return dates[weekId] || "2026-04-13";
};

// --- Components ---

const RenderShape = ({
  shape,
  color,
  size,
}: {
  shape: string;
  color?: string;
  size: number;
}) => {
  const c = color || "#059669";
  switch (shape) {
    case "square":
      return (
        <div
          style={{
            width: size,
            height: size,
            backgroundColor: c,
            borderRadius: "4px",
          }}
        />
      );
    case "circle":
      return (
        <div
          style={{
            width: size,
            height: size,
            backgroundColor: c,
            borderRadius: "50%",
          }}
        />
      );
    case "triangle":
      return (
        <div
          style={{
            width: 0,
            height: 0,
            borderLeft: `${size / 2}px solid transparent`,
            borderRight: `${size / 2}px solid transparent`,
            borderBottom: `${size}px solid ${c}`,
          }}
        />
      );
    case "star":
      return <Star fill={c} stroke="none" size={size} />;
    default:
      return null;
  }
};

const Pattern = ({
  type,
  color,
}: {
  type: AppTheme["patternType"];
  color: string;
}) => {
  if (type === "dots") {
    return (
      <div
        className="absolute inset-0 opacity-10 pointer-events-none"
        style={{
          backgroundImage: `radial-gradient(${color} 2px, transparent 2px)`,
          backgroundSize: "24px 24px",
        }}
      />
    );
  }
  if (type === "waves") {
    return (
      <div
        className="absolute inset-0 opacity-10 pointer-events-none"
        style={{
          backgroundImage: `radial-gradient(ellipse at 50% -20%, ${color}, transparent), radial-gradient(ellipse at 50% 120%, ${color}, transparent)`,
        }}
      />
    );
  }
  if (type === "stars") {
    return (
      <div className="absolute inset-0 opacity-10 pointer-events-none">
        <div
          className="w-full h-full"
          style={{
            backgroundImage: `url("data:image/svg+xml,%3Csvg width='20' height='20' viewBox='0 0 20 20' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M10 0l2 7h7l-5 4 2 7-6-4-6 4 2-7-5-4h7l2-7z' fill='${encodeURIComponent(color)}' fill-opacity='1'/%3E%3C/svg%3E")`,
            backgroundSize: "40px 40px",
          }}
        />
      </div>
    );
  }
  if (type === "clouds") {
    return (
      <div className="absolute inset-0 opacity-5 pointer-events-none">
        <div
          className="w-full h-full"
          style={{
            backgroundImage: `url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M45 40a10 10 0 1 1-1.3-19.9 15 15 0 1 1-24.3-3 12 12 0 1 1-1.3 22.9H45z' fill='${encodeURIComponent(color)}' fill-opacity='1'/%3E%3C/svg%3E")`,
            backgroundSize: "100px 100px",
          }}
        />
      </div>
    );
  }
  return null;
};

