interface SearchableSelectProps {
  value: string;
  onChange: (value: string) => void;
  options: { id: string; name: string }[];
  placeholder: string;
}

function SearchableSelect({
  value,
  onChange,
  options,
  placeholder,
}: SearchableSelectProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState("");
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        containerRef.current &&
        !containerRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
    }
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [isOpen]);

  const selectedOption = options.find((o) => String(o.id) === String(value));

  const filtered = options.filter((o) =>
    o.name.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <div
      ref={containerRef}
      className={cn(
        "relative w-full text-left",
        isOpen ? "z-[99] isolate" : "z-10",
      )}
    >
      <button
        type="button"
        onClick={() => {
          setIsOpen(!isOpen);
          setSearch("");
        }}
        className={cn(
          "w-full px-2 py-1.5 text-[9px] font-black rounded-lg border-2 transition-all outline-none flex items-center justify-between gap-1 text-left",
          value
            ? "bg-[#064E3B] text-white border-2 border-[#064E3B]"
            : "bg-white/80 border-emerald-100 text-[#064E3B]/30 opacity-60 hover:opacity-100 focus:opacity-100",
        )}
      >
        <span className="truncate">
          {selectedOption ? selectedOption.name : placeholder}
        </span>
        <span className="shrink-0 text-[8px] opacity-60">▼</span>
      </button>

      {isOpen && (
        <div className="absolute left-0 mt-1 w-full min-w-[160px] bg-white border border-emerald-100 rounded-xl shadow-xl z-50 overflow-hidden flex flex-col max-h-[220px]">
          <div className="p-1.5 border-b border-dashed border-emerald-50 bg-emerald-50/20">
            <input
              type="text"
              autoFocus
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Type to search..."
              className="w-full px-2 py-1 text-[9px] font-bold border border-emerald-100 rounded-md outline-none focus:border-[#059669] focus:ring-1 focus:ring-[#059669]/20 text-gray-800"
              onClick={(e) => e.stopPropagation()}
            />
          </div>

          <div className="overflow-y-auto flex-1 custom-scrollbar">
            <button
              type="button"
              onClick={() => {
                onChange("");
                setIsOpen(false);
              }}
              className={cn(
                "w-full text-left px-2.5 py-1.5 text-[9px] font-black hover:bg-emerald-50/50 transition-colors uppercase",
                !value ? "bg-emerald-50 text-[#064E3B]" : "text-[#064E3B]/40",
              )}
            >
              No Teacher
            </button>

            {filtered.length > 0 ? (
              filtered.map((o) => (
                <button
                  type="button"
                  key={o.id}
                  onClick={() => {
                    onChange(o.id);
                    setIsOpen(false);
                  }}
                  className={cn(
                    "w-full text-left px-2.5 py-1.5 text-[9px] font-black hover:bg-emerald-50 transition-colors truncate block",
                    value === o.id
                      ? "bg-emerald-100 text-[#064E3B]"
                      : "text-[#064E3B]",
                  )}
                >
                  {o.name}
                </button>
              ))
            ) : (
              <div className="px-2.5 py-2 text-[9px] font-bold text-gray-400 italic text-center">
                No matching teachers
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/* =====================================================================
   LOCKED PERIOD BLOCKS

   A locked block reserves a period for a subject before the generator runs.
   The subject is written into the timetable up front and the period is then
   unavailable, so nothing can ever be allocated on top of it.

   target: "ALL" | "KS1".."KS4" | a year group name ("Year 3")
   period: the period NUMBER as shown on the timetable (P1, P2 ...), not the
           raw slot index -- the index differs between primary and secondary.
   double: reserve this period AND the one next to it.
   ===================================================================== */
export type LockedBlock = {
  id: string;
  target: string;
  day: string;
  period: number;
  subject: string;
  double: boolean;
};

export const KEY_STAGE_OF = (yg: string): string => {
  const n = parseInt(String(yg).replace(/\D/g, ""), 10);
  if (n >= 1 && n <= 2) return "KS1";
  if (n >= 3 && n <= 6) return "KS2";
  if (n >= 7 && n <= 9) return "KS3";
  if (n >= 10 && n <= 11) return "KS4";
  return "CAMBRIDGE PLUS";
};

const blockAppliesTo = (b: LockedBlock, yg: string) =>
  b.target === "ALL" || b.target === yg || b.target === KEY_STAGE_OF(yg);

