  const saveProject = async (
    lessonContent: EduContent,
    title: string,
    category: string,
  ) => {
    if (!user) return;
    const projectId =
      currentProjectId || Math.random().toString(36).substring(2, 15);
    // Worked out here rather than at each of the save buttons, so every one of
    // them files the project under the same name.
    const savedTitle = deriveProjectTitle(lessonContent, title);
    // The view holds the truth about what is being saved — every save button
    // is rendered inside one. workspaceMode can lag behind it, and a lesson
    // plan filed as "slides" is invisible in All Plans.
    const VIEW_CATEGORY: Record<string, string> = {
      "lesson-plan": "lesson-plan",
      slides: "slides",
      worksheet: "worksheet",
      notes: "notes",
      "reading-program": "reading-program",
    };
    const savedCategory =
      VIEW_CATEGORY[currentView as string] || category || "slides";
    const projectData = {
      id: projectId,
      userId: user.uid,
      // Only file into a folder this teacher actually owns. Saving into a
      // folder id left behind by another account put the project somewhere
      // they could never open.
      folderId:
        activeFolderId && folders.some((f: any) => f?.id === activeFolderId)
          ? activeFolderId
          : null,
      timestamp: Date.now(),
      title: savedTitle,
      category: savedCategory,
      status: "draft",
      teacherName: teacherName,
      // Carry the name back into the content too, so reopening the project
      // shows the same title everywhere instead of the placeholder again.
      content: isPlaceholderTitle(lessonContent?.lessonTitle)
        ? { ...lessonContent, lessonTitle: savedTitle }
        : lessonContent,
      settings: {
        includeStory,
        isTemplateMode,
        workspaceMode,
      },
    };

    try {
      await store.put("projects", projectId, projectData);
      setCurrentProjectId(projectId);
      alert("Project saved successfully!");
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `projects/${projectId}`);
    }
  };

  const createFolder = async (name: string) => {
    if (!user || !name.trim()) return;
    const folderId = Math.random().toString(36).substring(2, 15);
    try {
      await store.put("folders", folderId, {
        id: folderId,
        userId: user.uid,
        name,
        timestamp: Date.now(),
      });
      setNewFolderName("");
      setIsCreatingFolder(false);
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, `folders/${folderId}`);
    }
  };

  const deleteProject = async (projectId: string) => {
    if (!user) return;
    if (!window.confirm("Are you sure you want to delete this project?"))
      return;
    try {
      await store.remove("projects", projectId);
      if (currentProjectId === projectId) {
        clearWorkspace();
      }
    } catch (err) {
      handleFirestoreError(err, OperationType.DELETE, `projects/${projectId}`);
    }
  };

  const deleteFolder = async (folderId: string) => {
    if (!user) return;
    // Without this, a missing id matches every project whose folderId is null —
    // that is, everything the teacher never filed — and deletes the lot. The
    // Firestore version was saved from this by accident: doc(db, "folders",
    // undefined) throws before batch.commit(), so nothing was written. Deleting
    // through the store has no such accident to rely on, so the guard is
    // explicit, and the filter below refuses a falsy folderId a second time.
    if (!folderId) {
      console.warn("deleteFolder called without a folder id; ignoring.");
      return;
    }
    if (!window.confirm("Delete folder and all its contents?")) return;
    try {
      // The store has no batch, so this is no longer atomic. The projects go
      // first on purpose: if the folder delete then fails the teacher sees an
      // empty folder, which they can delete again, rather than projects left
      // pointing at a folder that no longer exists and no way to reach them.
      const projectsInFolder = userProjects.filter(
        (p) => !!p.folderId && p.folderId === folderId,
      );
      await Promise.all(
        projectsInFolder.map((p) => store.remove("projects", p.id)),
      );
      await store.remove("folders", folderId);
      if (activeFolderId === folderId) setActiveFolderId(null);
    } catch (err) {
      handleFirestoreError(err, OperationType.WRITE, "batch-delete-folder");
    }
  };

  const [lessonInput, setLessonInput] = useState("");
  // Optional extra instructions for generation, separate from the topic.
  const [lessonInstructions, setLessonInstructions] = useState("");
  // --- ZeraBot chat (ChatGPT-style Q&A + poster/image generation) ---
  // An "artifact" is a downloadable doc / interactive HTML the assistant builds.
  type ChatArtifact = { type: "html" | "doc"; html: string; title: string };
  type ChatMessage = {
    role: "user" | "model";
    text: string;
    image?: string;
    artifact?: ChatArtifact;
  };
  const [chatOpen, setChatOpen] = useState(false);
  const [chatInput, setChatInput] = useState("");
  const [chatLoading, setChatLoading] = useState(false);
  const [chatMessages, setChatMessages] = useState<ChatMessage[]>([]);
  const chatScrollRef = useRef<HTMLDivElement>(null);
  // Persisted log of the teacher's own requests to the assistant (per user,
  // kept in localStorage so it survives reloads and appears on this device).
  type HistoryItem = { text: string; ts: number };
  const [requestHistory, setRequestHistory] = useState<HistoryItem[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const historyKey = () => `zera_assistant_history_${user?.uid || "anon"}`;
  const recordRequest = (text: string) => {
    setRequestHistory((prev) => {
      const next = [
        { text, ts: Date.now() },
        ...prev.filter((h) => h.text !== text),
      ].slice(0, 100);
      try {
        localStorage.setItem(historyKey(), JSON.stringify(next));
      } catch {
        /* ignore quota / private-mode errors */
      }
      return next;
    });
  };
  const clearRequestHistory = () => {
    setRequestHistory([]);
    try {
      localStorage.removeItem(historyKey());
    } catch {
      /* ignore */
    }
  };
  const fmtHistoryTime = (ts: number) => {
    const min = Math.floor((Date.now() - ts) / 60000);
    if (min < 1) return "just now";
    if (min < 60) return `${min}m ago`;
    const hr = Math.floor(min / 60);
    if (hr < 24) return `${hr}h ago`;
    const day = Math.floor(hr / 24);
    if (day < 7) return `${day}d ago`;
    return new Date(ts).toLocaleDateString();
  };
  // WYSIWYG editing of an assistant-generated document/HTML artifact.
  const [editArtifact, setEditArtifact] = useState<{ index: number; title: string } | null>(null);
  const editFrameRef = useRef<HTMLIFrameElement>(null);
  // Publishing a worksheet to the Cloudflare worker → short public student link.
  const [publishing, setPublishing] = useState(false);
  const [publishResult, setPublishResult] = useState<{ url: string; note?: string } | null>(null);
  const [linkCopied, setLinkCopied] = useState(false);
  const copyPublishedLink = (url: string) => {
    navigator.clipboard
      .writeText(url)
      .then(() => {
        setLinkCopied(true);
        setTimeout(() => setLinkCopied(false), 1800);
      })
      .catch(() => {});
  };
  // ===== HTML Host tool — paste any HTML, publish it, share a student link =====
  const [htmlHostInput, setHtmlHostInput] = useState("");
  const [htmlHostCode, setHtmlHostCode] = useState("");
  const [zipStatus, setZipStatus] = useState<string | null>(null);
  // Upload HTML to the worker and show the short shareable link (+ QR).
  const [isBuildingWs, setIsBuildingWs] = useState(false);
  // Open an assistant worksheet in the Assessment Hub's interactive worksheet
  // design: structure its questions into a worksheet, then render with
  // buildInteractiveHTML (themed sheet, Name/Class/Date, section pills).
  const openAsAssessmentWorksheet = async (artifact: ChatArtifact) => {
    let bodyText = "";
    try {
      const doc = new DOMParser().parseFromString(artifact.html, "text/html");
      bodyText = (doc.body?.textContent || "").replace(/[ \t]+/g, " ").trim();
    } catch {
      bodyText = artifact.html.replace(/<[^>]+>/g, " ");
    }
    setIsBuildingWs(true);
    try {
      const raw = await askAI(
        `Convert the worksheet below into JSON ONLY (no markdown fences, no commentary). Shape: {"title":"...","sections":[{"title":"...","instructions":"...","wordBank":["..."],"questions":[{"text":"...","type":"...","options":["..."]}]}]}. "type" is one of "multiple-choice","true-false","short-answer","fill-in-the-blanks". Include "options" ONLY for multiple-choice (3-4) and true-false (["True","False"]).\n\nRULES — be FAITHFUL to the source:\n- Keep EVERY question. Use the worksheet's EXACT wording. Do NOT invent, drop, summarise, rephrase, reorder, or change any question, option, instruction, or section title.\n- If the worksheet shows words inside a box or "word bank" (single words/short terms students choose from), put those words in that section's "wordBank" array, keeping the same words and spelling. Only single words or short terms — never full sentences. Omit "wordBank" if the section has none.\n\nWORKSHEET:\n"""${bodyText.slice(0, 6000)}"""`,
        [],
      );
      let ws: any;
      try {
        ws = JSON.parse(stripCodeFences(raw));
      } catch {
        throw new Error("Couldn't structure that worksheet — try Open or Designs instead.");
      }
      if (!ws?.sections?.length) throw new Error("No questions found to build a worksheet.");
      const title = artifact.title || ws.title || "Worksheet";
      // Don't inject the app's global subject (e.g. "Science") into the heading —
      // an assistant worksheet has no chosen subject, so the plain "Open" view
      // never shows it. Keep them consistent by leaving the subject blank.
      const html = buildInteractiveHTML(ws, title, interactiveDesign, "worksheet", "");
      setInteractiveDoc({ html, title, ws, design: interactiveDesign, kind: "worksheet", subject: "" });
    } catch (e: any) {
      alert(e?.message || "Couldn't build the interactive worksheet.");
    } finally {
      setIsBuildingWs(false);
    }
  };
  // The Cloudflare Pages host that stores & serves published pages. Short,
  // reliable, and no long account name — links are e.g. zera-4ag.pages.dev/cat.
  const WORKSHEET_HOST_DEFAULT = "https://zera-4ag.pages.dev";

  // Upload a page to the share host and hand back its public link.
  const uploadSharedHtml = async (
    html: string,
    code: string = "",
  ): Promise<string> => {
    const res = await fetch(`${WORKSHEET_HOST_DEFAULT}/upload`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ html: ensurePrintableA4(html), code }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data?.url)
      throw new Error(data?.error || `Publish failed (HTTP ${res.status})`);
    return data.url as string;
  };

  const publishHtml = async (html: string, presetCode?: string) => {
    // When a preset code is supplied (e.g. from the HTML Host tool) skip the
    // prompt entirely — an empty string just means "use a random code".
    const code = (
      presetCode !== undefined
        ? presetCode
        : window.prompt(
            "Optional: a short memorable code for the link (e.g. cat → /s/cat). Leave blank for a random one.",
            "",
          ) || ""
    ).trim();
    setPublishing(true);
    try {
      // Publish an A4-print-ready version so the shared link prints cleanly.
      const res = await fetch(`${WORKSHEET_HOST_DEFAULT}/upload`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ html: ensurePrintableA4(html), code }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data?.url)
        throw new Error(data?.error || `Publish failed (HTTP ${res.status})`);
      const url = data.url as string;
      setPublishResult({ url });
      try {
        await navigator.clipboard.writeText(url);
      } catch {
        /* ignore */
      }
    } catch (e: any) {
      alert(
        `Couldn't publish: ${e?.message || e}\n\nMake sure you're online and try again.`,
      );
    } finally {
      setPublishing(false);
    }
  };

  // Does this message ask for a downloadable interactive HTML page?
  const looksLikeHtmlRequest = (q: string) =>
    /\b(interactive html|html page|html document|html file|web ?page|landing page|as html|in html|html version)\b/i.test(
      q,
    );
  // Does this message ask the assistant to create a document/worksheet/etc.?
  const looksLikeDocRequest = (q: string) =>
    /\b(document|\bdoc\b|word doc|\.docx?|worksheet|lesson plan|letter|report|essay|memo|notes|handout|article|story|printable|certificate|create a|make a|write a|generate a|draft a)\b/i.test(
      q,
    );
  // Strip ```html ... ``` / ``` fences and leading commentary the model may add.
  const stripCodeFences = (s: string) =>
    String(s || "")
      .replace(/^[\s\S]*?```(?:html|HTML)?\s*\n?/, (m) => (m.includes("```") ? "" : m))
      .replace(/```[\s\S]*$/, "")
      .trim() || String(s || "").trim();
  // Wrap plain document body HTML in a clean, printable A4 page.
  const wrapDocHtml = (title: string, bodyHtml: string) =>
    `<!doctype html><html lang="en"><head><meta charset="utf-8"/>` +
    `<meta name="viewport" content="width=device-width, initial-scale=1"/>` +
    `<title>${zEsc(title)}</title><style>` +
    `@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;800&family=Comic+Neue:wght@400;700&display=swap');` +
    `*{box-sizing:border-box}body{font-family:'Comic Neue','Segoe UI',system-ui,sans-serif;color:#1e293b;background:#f1f5f9;margin:0;padding:24px;line-height:1.7}` +
    `.sheet{max-width:820px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:48px 56px;box-shadow:0 14px 40px rgba(0,0,0,.08)}` +
    `h1,h2,h3{font-family:'Baloo 2',sans-serif;color:#0d9488;line-height:1.2}h1{font-size:30px;margin:0 0 6px}h2{font-size:21px;margin:26px 0 8px}h3{font-size:17px}` +
    `p{margin:0 0 12px}ul,ol{margin:0 0 14px 22px}li{margin:4px 0}table{border-collapse:collapse;width:100%;margin:12px 0}th,td{border:1px solid #cbd5e1;padding:8px 10px;text-align:left}th{background:#f0fdfa}` +
    `.bar{max-width:820px;margin:0 auto 16px;text-align:center}.bar button{font-family:inherit;font-weight:800;border:0;background:#0d9488;color:#fff;padding:10px 22px;border-radius:999px;cursor:pointer}` +
    `@media print{body{background:#fff;padding:0}.sheet{box-shadow:none;border:0}.bar{display:none}}` +
    `</style></head><body><div class="bar"><button onclick="window.print()">🖨️ Print / Save as PDF</button></div>` +
    `<div class="sheet">${bodyHtml}</div></body></html>`;

  /* Make any HTML print cleanly on A4 before it is published: an @page A4 rule,
     white background, sensible page-break avoidance, and a floating print
     button. Idempotent and safe for already-styled pages -- a page that already
     has its own print button keeps it (we don't add a second). Fragments (no
     <html>/<body>) are wrapped in the printable A4 sheet above. */
  const ensurePrintableA4 = (raw: string) => {
    let html = String(raw || "").trim();
    if (!html) return html;

    const isFullDoc =
      /<!doctype/i.test(html) ||
      /<html[\s>]/i.test(html) ||
      /<body[\s>]/i.test(html);
    if (!isFullDoc) return wrapDocHtml("Zera Worksheet", html);

    if (html.includes("zera-a4-print")) return html; // already processed

    const style =
      `<style id="zera-a4-print">@media print{` +
      `@page{size:A4;margin:14mm}` +
      `html,body{background:#fff!important;margin:0!important;padding:0!important;` +
      `-webkit-print-color-adjust:exact;print-color-adjust:exact}` +
      `.zera-print-hide{display:none!important}` +
      `img,svg,table,tr,td,figure,pre,blockquote,section,article,` +
      `.card,.question,.q,.item,li{break-inside:avoid;page-break-inside:avoid}` +
      `h1,h2,h3,h4{break-after:avoid;page-break-after:avoid}` +
      `}</style>`;

    if (/<\/head>/i.test(html))
      html = html.replace(/<\/head>/i, `${style}</head>`);
    else if (/<body[^>]*>/i.test(html))
      html = html.replace(/(<body[^>]*>)/i, `$1${style}`);
    else html = style + html;

    // Add a floating print button only if the page has none of its own.
    if (!/window\.print\s*\(/i.test(raw)) {
      const btn =
        `<button class="zera-print-hide" onclick="window.print()" ` +
        `style="position:fixed;top:14px;right:14px;z-index:2147483647;` +
        `font:600 13px/1 system-ui,-apple-system,sans-serif;background:#0d9488;` +
        `color:#fff;border:0;padding:10px 16px;border-radius:999px;` +
        `box-shadow:0 4px 14px rgba(0,0,0,.18);cursor:pointer">` +
        `🖨️ Print / Save as PDF</button>`;
      if (/<body[^>]*>/i.test(html))
        html = html.replace(/(<body[^>]*>)/i, `$1${btn}`);
      else html = btn + html;
    }
    return html;
  };
  // Trigger a browser download of a text/HTML artifact.
  const downloadTextFile = (filename: string, mime: string, content: string) => {
    const blob = new Blob([content], { type: `${mime};charset=utf-8` });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  };
  const safeFileName = (s: string) =>
    (s || "zera-document").replace(/[\\/:*?"<>|]+/g, "").replace(/\s+/g, "_").slice(0, 60);
  // Empty the hint text inside answer/typing boxes so students see blank fields.
  // Removes placeholder attributes, hint `value=` attributes, bracketed hints
  // like "[ Click & type here ]", and standalone "type here"/"write your answer"
  // phrases that the AI sometimes drops as visible text inside the boxes.
  const clearInputPlaceholders = (html: string) => {
    // Broad set — safe to remove inside attributes and [ ... ] hint brackets.
    const HINT =
      "(?:click\\s*&?\\s*type|type\\s*(?:your\\s*answer\\s*)?here|write\\s*(?:your\\s*)?answer|your\\s*answer\\s*here|enter\\s*(?:your\\s*)?(?:answer|text))";
    // Narrow set — only these are removed from free text, so legitimate
    // instructions like "Write your answer below" are NOT touched.
    const BARE = "(?:click\\s*&?\\s*type\\s*here|click\\s*to\\s*type|type\\s*here|type\\s*your\\s*answer\\s*here)";
    return String(html || "")
      // placeholder="..." / placeholder='...'
      .replace(/\s+placeholder\s*=\s*("[^"]*"|'[^']*')/gi, "")
      // value="...type here..." (pre-filled hint values)
      .replace(new RegExp(`\\s+value\\s*=\\s*("[^"]*?${HINT}[^"]*"|'[^']*?${HINT}[^']*')`, "gi"), "")
      // bracketed hints as text content: "[ Click & type here ]"
      .replace(new RegExp(`\\[\\s*[^\\]\\n]{0,40}?${HINT}[^\\]\\n]{0,20}?\\s*\\]`, "gi"), "")
      // bare hint phrases as text content (narrow, instruction-safe)
      .replace(new RegExp(`\\b${BARE}\\b`, "gi"), "");
  };
  // Use the AI's own title/heading for the artifact (NOT the user's instruction,
  // which otherwise leaks into the viewer header and the file name).
  const extractArtifactTitle = (html: string, fallback: string) => {
    const s = String(html || "");
    const m =
      s.match(/<title[^>]*>([\s\S]*?)<\/title>/i) ||
      s.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) ||
      s.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i);
    const t = m ? m[1].replace(/<[^>]+>/g, "").replace(/\s+/g, " ").trim() : "";
    return (t || fallback).slice(0, 60);
  };

  const sendChat = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const q = chatInput.trim();
    if (!q || chatLoading) return;
    const history: ChatTurn[] = chatMessages.map((m) => ({
      role: m.role,
      text: m.text,
    }));
    setChatMessages((prev) => [...prev, { role: "user", text: q }]);
    recordRequest(q);
    setChatInput("");
    setChatLoading(true);
    try {
      if (looksLikeHtmlRequest(q)) {
        const raw = await askAI(
          `You are an expert educational web designer. Build a COMPLETE, self-contained, standalone HTML5 document (inline <style> and inline <script>, NO external files, CDNs or frameworks) that fulfils this request: "${q}".

DESIGN: Make it VERY colourful, vibrant and genuinely attractive for school students — bold lively palettes, gradients, playful rounded cards, fun emoji/icons, smooth hover and click animations, and big clear tap targets. Never plain or dull. Keep it mobile-friendly so it works well on a phone. Use a proper descriptive title for the topic — do NOT use the request sentence as the title, and do NOT restate, quote, echo or display the request/instruction text anywhere in the page.

INTERACTIVE & SELF-CHECKING (REQUIRED — this is the whole point): The student does the activity ON SCREEN and then checks their own answers. So:
- Every question must be answerable in the browser: clickable multiple-choice options, True/False buttons, text inputs for fill-in / short-answer, or click-to-match. No "print it out" steps.
- Embed the correct answer for EVERY question inside the inline <script> as an answer key.
- Add ONE big, obvious "Check Answers" button. When clicked it grades everything client-side and: marks each question with a green ✓ if correct or a red ✗ if wrong, reveals the correct answer next to anything the student got wrong, and shows a total score (e.g. "8 / 10") with a cheerful message. For typed answers, compare case-insensitively, trim spaces, and accept obvious equivalent spellings.
- Add a "Try Again" button that clears all the marks and the score so the student can retry.
- Do NOT show which answers are correct until the student presses Check Answers.

Any box where a student types an answer MUST START COMPLETELY EMPTY — no placeholder, no "[ Click & type here ]", no "type here", no "write your answer", no brackets, no hint of any kind.

Return ONLY the raw HTML starting at <!doctype html> — no markdown fences, no explanation.`,
          history,
        );
        const html = clearInputPlaceholders(stripCodeFences(raw));
        setChatMessages((prev) => [
          ...prev,
          {
            role: "model",
            text: "Here's your interactive HTML — open it or download it below. ✨",
            artifact: {
              type: "html",
              html,
              title: extractArtifactTitle(html, "Interactive Worksheet"),
            },
          },
        ]);
      } else if (looksLikeDocRequest(q)) {
        const raw = await askAI(
          `Create the content for a document that fulfils this request: "${q}". Use a proper descriptive heading for the topic — do NOT use the request sentence as the heading, and do NOT restate, quote, echo or display the request/instruction text anywhere in the document. Produce only the finished document content. Return clean semantic HTML body content ONLY (use <h1>, <h2>, <p>, <ul>/<li>, <table> where helpful). Do NOT include <html>, <head> or <body> tags, no markdown code fences, no commentary.`,
          history,
        );
        const body = stripCodeFences(raw);
        const docTitle = extractArtifactTitle(body, "Document");
        const html = clearInputPlaceholders(wrapDocHtml(docTitle, body));
        setChatMessages((prev) => [
          ...prev,
          {
            role: "model",
            text: "Here's your document — download it as Word or HTML, or open it below. 📄",
            artifact: { type: "doc", html, title: docTitle },
          },
        ]);
      } else {
        const answer = await askAI(q, history);
        setChatMessages((prev) => [...prev, { role: "model", text: answer }]);
      }
    } catch (err: any) {
      const raw = err?.message || "";
      const quota = /429|quota|rate/i.test(raw);
      setChatMessages((prev) => [
        ...prev,
        {
          role: "model",
          text:
            "⚠️ Sorry, I couldn't get an answer. " +
            (quota
              ? "The AI is busy right now — please wait a moment and try again."
              : raw || "Please check the AI key configuration and try again."),
        },
      ]);
    } finally {
      setChatLoading(false);
    }
  };

  useEffect(() => {
    if (chatScrollRef.current) {
      chatScrollRef.current.scrollTop = chatScrollRef.current.scrollHeight;
    }
  }, [chatMessages, chatLoading, chatOpen]);
  // Load this user's saved request history whenever the signed-in user changes.
  useEffect(() => {
    try {
      const raw = localStorage.getItem(historyKey());
      setRequestHistory(raw ? JSON.parse(raw) : []);
    } catch {
      setRequestHistory([]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);
  const [yearGroup, setYearGroup] = useState("Year 3");
  const [subject, setSubject] = useState("");
  const [lexileLevel, setLexileLevel] = useState("400-500");
  const [targetRelevelLexile, setTargetRelevelLexile] = useState("400-500");
  const [isReleveling, setIsReleveling] = useState(false);
  // True while the "Generate Pack" action is creating the chosen Lexile levels
  // of the reading passage.
  const [isGeneratingPassagePack, setIsGeneratingPassagePack] = useState(false);
  // Which Lexile levels the "Generate Pack" action will create. Defaults to all;
  // the teacher can pick a subset.
  const [packLevels, setPackLevels] = useState<string[]>(
    PASSAGE_LEXILE_LEVELS.map((l) => l.id),
  );
  // True while building the interactive HTML passage (incl. AI hero image).
  const [isBuildingInteractivePassage, setIsBuildingInteractivePassage] = useState(false);
  const [targetWordCount, setTargetWordCount] = useState<string>("300-500");
  const [selectedSuiteLevel, setSelectedSuiteLevel] =
    useState<string>("400-500");
  const [selectedStoryStyle, setSelectedStoryStyle] = useState<string>("classic");
  // Differentiated worksheet pack — same questions worded per Lexile level
  const [diffWsLevels, setDiffWsLevels] = useState<string[]>([
    "200-300",
    "400-500",
    "600-700",
  ]);
